print(f"Total C1 lessons defined: {len(lessons)}")
total_items = sum(len(items) for _, _, _, _, items in lessons)
print(f"Total C1 items defined: {total_items}")

with open(c1_file, "w", encoding="utf-8") as f:
    f.write('''#!/usr/bin/env python3
"""
Comprehensive Exercise Generator for C1 Grammar.
Generates exactly 20 exercises for each of the 10 C1 grammar lessons = 200 exercises.
"""
from mcq_balancer import McqBalancer

balancer = McqBalancer(seed=704)

def make_ex(ex_id, target_id, level, prompt_en, prompt_tr, stem, correct, distractors, exp_en, exp_tr, dist_exps, diff="stretch"):
    options, idx = balancer.balance_options(correct, distractors)
    return {
        "id": ex_id,
        "target_content_id": target_id,
        "cefr_level": level,
        "skill_domain": "grammar",
        "exercise_type": "multiple_choice",
        "prompt_en": prompt_en,
        "prompt_tr_hint": prompt_tr,
        "stem": stem,
        "options": options,
        "correct_answer": correct,
        "explanation_en": exp_en,
        "explanation_tr": exp_tr,
        "distractor_explanations": dist_exps,
        "difficulty": diff,
        "status": "APPROVED",
        "version": 1
    }

C1_EXERCISES = []

def add_lesson(lesson_id, short_id, items, prompt_en, prompt_tr):
    for i, data in enumerate(items, 1):
        stem, corr, dists, en_exp, tr_exp, d_exps = data
        C1_EXERCISES.append(make_ex(f"exercise.c1.{short_id}-{i:02d}", lesson_id, "C1",
                                    prompt_en, prompt_tr, stem, corr, dists, en_exp, tr_exp, d_exps))

''')
    for lesson_id, short_id, p_en, p_tr, items in lessons:
        f.write(f'# {lesson_id}\n')
        f.write(f'add_lesson("{lesson_id}", "{short_id}", [\n')
        for stem, corr, dists, en_exp, tr_exp, d_exps in items:
            f.write(f'    ({repr(stem)}, {repr(corr)}, {repr(dists)},\n')
            f.write(f'     {repr(en_exp)}, {repr(tr_exp)},\n')
            f.write(f'     {repr(d_exps)}),\n')
        f.write(f'], {repr(p_en)}, {repr(p_tr)})\n\n')

print("Wrote generate_exercises_c1.py successfully.")
